    context: { gameType: 'cash', blinds: '1/2', position: 'BB vs BTN', effectiveStack: '60BB', street: 'flop', pot: '20', heroHand: ['J♥', '8♥'], board: ['A♥', '5♥', '2♦'], action: 'BTN mise 10$.' },
