    question: 'Tu as KQ sur J-T-9-2-8. Tu as une quinte (Q-J-T-9-8). BB check. Quel sizing ?', xp: 55,
    options: [
      { label: 'Check — le board est trop coordonné', isCorrect: false, explanation: 'Tu AS une quinte! Checker avec une main très forte est une erreur de valeur. Bet pour extraire.' },
      { label: 'Bet 70-80% pour valeur', isCorrect: true, explanation: 'Correct ! Tu as une quinte Q-J-T-9-8. C\'est une main très forte. Bet pour valeur contre les mains plus faibles de BB (paires, two pairs, flush draws...).' },
      { label: 'Overbet 2x pot — tu as probablement les nuts', isCorrect: false, explanation: 'La quinte Q haute n\'est pas les nuts sur ce board (K ou A high straight serait meilleure). L\'overbet peut faire fuir des mains qui paieraient un bet normal.' },
      { label: 'Fold — trop de meilleures quintes possibles', isCorrect: false, explanation: 'Folder une quinte en river est presque toujours une erreur. Tu as une très bonne main — joue-la pour valeur.' },
    ],
    lesson: 'Reconnaître quand tu as une main forte est fondamental. Sur J-T-9-2-8, K-Q fait une quinte. Bet pour valeur sans hesitation.',
