    question: 'Un LAG ouvre en CO. Tu as TT en BTN. 3-bet ou call ?', xp: 80,
    options: [
      { label: 'Call — TT joue mieux post-flop que préflop', isCorrect: false, explanation: 'Call est défendable mais sous-optimal vs un LAG. TT est suffisamment fort pour 3-bet, surtout vs un range large d\'un LAG.' },
      { label: '3-bet à 10BB — valeur et information', isCorrect: true, explanation: 'Correct ! Face à un LAG qui ouvre large, 3-bet TT est optimal. Tu extractes la valeur vs ses mains dominées (22-99, suited connectors) et prends l\'initiative. Si le LAG 4-bet, tu peux évaluer.' },
      { label: 'Fold — TT est trop faible contre un LAG actif', isCorrect: false, explanation: 'Folder TT serait une erreur grave. TT est dans le top 4% des mains.' },
      { label: '3-bet all-in pour forcer un fold', isCorrect: false, explanation: 'All-in à 100BB avec TT est trop extrême. Le LAG callera avec AQ, AK, JJ+ et tu seras souvent en flip ou derrière.' },
    ],
    lesson: 'Face à un LAG avec un range large, 3-bet TT pour valeur. Tu extrais de la valeur vs ses mains faibles et prends l\'initiative post-flop.',
