    question: 'Près de la bulle (18/20 payés). BTN all-in. Tu as A8o et 12000 chips. Call ou fold ?', xp: 90,
    options: [
      { label: 'Call — A8o est assez fort', isCorrect: false, explanation: 'Près de la bulle, l\'ICM impose un jeu plus conservateur. A8o vs un range BTN peut être un flip ou légèrement favorable, mais le risque ICM de ne pas atteindre le money est élevé.' },
      { label: 'Fold — l\'ICM pénalise sévèrement une élimination ici', isCorrect: true, explanation: 'Correct ! Avec 2 joueurs hors de la bulle et une main marginale (A8o), le fold ICM est souvent correct. Atteindre le money a une valeur énorme. A8o vs un range large de BTN = flip dangereux ICM-wise.' },
      { label: 'Call — toujours profitable vs un range large', isCorrect: false, explanation: 'Même si le call est +EV en chips, l\'ICM pénalise ce risque près de la bulle. Fold est souvent meilleur en ICM EV.' },
      { label: 'Fold — A8o est trop faible pour jamais call', isCorrect: false, explanation: 'A8o peut caller dans d\'autres contextes. Ici c\'est spécifiquement l\'ICM bulle qui rend le fold optimal.' },
    ],
    lesson: 'Près de la bulle, l\'ICM impose un jeu plus conservateur. Même avec A8o face à un range large, le risque d\'élimination à 2 places de la bulle peut justifier le fold.',
