    question: 'Sur A72 rainbow, qui a l\'avantage de range — CO (preflop raiser) ou BB ?', xp: 90,
    options: [
      { label: 'BB — il a défendu avec plus de mains connectées', isCorrect: false, explanation: 'BB a défendu large mais CO ouvre en position avec un range fort. Sur A72 sec, CO a AA, AK, AQ, A7s, A2s dans son range — BB ne peut pas avoir tous ces combos.' },
      { label: 'CO — son range contient plus de As forts et overpairs', isCorrect: true, explanation: 'Correct ! CO (preflop raiser) a un range advantage sur A72. Il a : AA, AK, AQ, AJ, A7s dans son range d\'open. BB défend large mais a moins de As forts. CO peut donc c-bet haute fréquence avec un petit sizing sur ce board.' },
      { label: 'Égal — les deux défendent correctement', isCorrect: false, explanation: 'Le range advantage n\'est pas symétrique. CO a sélectionné un range plus fort en openrant.' },
      { label: 'BB — l\'out-of-position donne un avantage sur les boards secs', isCorrect: false, explanation: 'L\'OOP n\'avantage pas naturellement sur les boards secs. C\'est l\'IP raiser qui a l\'avantage de range ici.' },
    ],
    lesson: 'Le range advantage sur A72 sec va à CO (IP raiser). Son range contient plus de As forts et overpairs. Cela justifie un c-bet haute fréquence avec un sizing petit (25-33%).',
