    options: [
      { label: 'Call — AK est trop fort pour fold même en bubble', isCorrect: true, explanation: 'Correct ! AK est dans le top 5% des mains. Même avec un bubble factor élevé, AK est suffisamment fort pour call. La pression ICM en bulle ne justifie pas de folder une main de cette force.' },
      { label: 'Fold — le bubble factor crée une pression ICM massive', isCorrect: false, explanation: 'Avec AK, le fold serait trop conservateur même en bubble. AK a ~70% d\'équité vs la plupart des ranges de push SB.' },
      { label: 'Fold seulement si l\'adversaire a moins de 50BB de stack', isCorrect: false, explanation: 'Le bubble factor dépend des stacks de TOUS les joueurs et du payout, pas seulement des stacks heads-up.' },
      { label: 'La décision n\'est jamais affectée par l\'ICM avec AK', isCorrect: false, explanation: 'Faux — l\'ICM peut théoriquement influencer AK dans des spots extrêmes (bulle extreme avec 1 stack ultra-court qui va buster). En pratique, AK est presque toujours un call.' },
    ],
    lesson: 'Le bubble factor = ratio entre le chip EV et le tournament EV. Il quantifie la pression ICM. Avec AK, le bubble factor est rarement assez grand pour justifier un fold.',
    xp: 175,
